import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaMapMarkerAlt,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
  FaCheckCircle,
  FaTimesCircle,
  FaRedo,
  FaPlayCircle,
  FaTrashAlt,
} from "react-icons/fa";

import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";
import { Link } from "react-router-dom";

const API_URL = "https://iranaserviceapp.ir/test/api";
const CLEAR_IMAGE_URL =
  "https://iranaserviceapp.ir/test/files/clear";

const PERSIAN_DIGITS = "۰۱۲۳۴۵۶۷۸۹";

function toPersianDigits(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).replace(
    /\d/g,
    (digit) => PERSIAN_DIGITS[Number(digit)]
  );
}

function formatDate(dateString) {
  if (!dateString) {
    return "—";
  }

  const parts = String(dateString).split("/");

  if (parts.length !== 3) {
    return dateString;
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  if (year < 1700) {
    return `${toPersianDigits(year)}/${toPersianDigits(
      String(month).padStart(2, "0")
    )}/${toPersianDigits(
      String(day).padStart(2, "0")
    )}`;
  }

  try {
    const date = new Date(
      year,
      month - 1,
      day
    );

    return new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }
    ).format(date);
  } catch (error) {
    console.error(
      "DATE FORMAT ERROR:",
      error
    );

    return dateString;
  }
}

// =====================================================
// تشخیص وضعیت درخواست
// =====================================================

function getRequestStatus(request, clear) {
  const status = Number(request.status);
  const end = Number(request.end);
  const cleared = Number(request.cleared);
  const deleted = Number(request.deleted);

  // ===================================================
  // تسویه شده
  // ===================================================

  if (
    clear !== null &&
    clear !== undefined
  ) {
    return {
      type: "settled",
      text: "تسویه شده",
      className:
        "text-primary fw-semibold",
      icon: <FaCheckCircle />,
    };
  }

  // ===================================================
  // حذف توسط ادمین
  // ===================================================

  if (
    deleted === 1 ||
    (status === 4 && end === 2)
  ) {
    return {
      type: "admin_deleted",
      text: "حذف توسط ادمین",
      className:
        "text-danger fw-semibold",
      icon: <FaTrashAlt />,
    };
  }

  // ===================================================
  // کنسل توسط تعمیرکار
  // ===================================================

  if (status === -1) {
    return {
      type: "canceled",
      text: "کنسل توسط تعمیرکار",
      className:
        "text-danger fw-semibold",
      icon: <FaTimesCircle />,
    };
  }

  // ===================================================
  // مجدد فعالسازی شده
  // ===================================================

  if (
    status === 1 &&
    end === 2
  ) {
    return {
      type: "reactivated",
      text: "مجدد فعالسازی شده",
      className:
        "text-dark fw-semibold",
      icon: <FaRedo />,
    };
  }

  // ===================================================
  // تسویه شده
  // status = 1
  // end = 1
  // cleared = 1
  // ===================================================

  if (
    status === 1 &&
    end === 1 &&
    cleared === 1
  ) {
    return {
      type: "settled",
      text: "تسویه شده",
      className:
        "text-primary fw-semibold",
      icon: <FaCheckCircle />,
    };
  }

  // ===================================================
  // تمام شده و منتظر پرداخت
  // status = 1
  // end = 1
  // cleared = 0
  // ===================================================

  if (
    status === 1 &&
    end === 1 &&
    cleared === 0
  ) {
    return {
      type: "waiting_payment",
      text: "تمام شده و منتظر پرداخت",
      className:
        "text-success fw-semibold",
      icon: <FaCoins />,
    };
  }

  // ===================================================
  // درحال اجرا
  // status = 1
  // end = 0
  // ===================================================

  if (
    status === 1 &&
    end === 0
  ) {
    return {
      type: "running",
      text: "درحال اجرا",
      className:
        "text-warning fw-semibold",
      icon: <FaPlayCircle />,
    };
  }

  // ===================================================
  // نامشخص
  // ===================================================

  return {
    type: "unknown",
    text: "وضعیت نامشخص",
    className:
      "text-muted fw-semibold",
    icon: <FaExclamationCircle />,
  };
}

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
      error: "",
    };

    this.handleBack =
      this.handleBack.bind(this);

    this.handleChat =
      this.handleChat.bind(this);

    this.handleAddRelated =
      this.handleAddRelated.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  getRequestDetail = async () => {
    const { id } =
      this.props.params;

    const token =
      localStorage.getItem("token");

    console.log(
      "REQUEST ID:",
      id
    );

    if (!id) {
      this.setState({
        loading: false,
        error:
          "شناسه درخواست پیدا نشد.",
      });

      return;
    }

    if (!token) {
      this.setState({
        loading: false,
        error:
          "توکن ورود پیدا نشد.",
      });

      return;
    }

    const url =
      `${API_URL}/detail?id=${encodeURIComponent(
        id
      )}`;

    console.log(
      "REQUEST DETAIL URL:",
      url
    );

    try {
      const response =
        await fetch(url, {
          method: "GET",

          headers: {
            Accept:
              "application/json",

            Authorization:
              `Bearer ${token}`,
          },
        });

      console.log(
        "HTTP STATUS:",
        response.status
      );

      if (!response.ok) {
        throw new Error(
          `HTTP ${response.status}`
        );
      }

      const data =
        await response.json();

      console.log(
        "REQUEST DETAIL API:",
        data
      );

      if (
        String(data.status) !==
        "1"
      ) {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error:
            data.message ||
            "اطلاعات درخواست پیدا نشد.",
        });

        return;
      }

      const request =
        data.request || null;

      const clear =
        data.clear || null;

      if (!request) {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error:
            "درخواست پیدا نشد.",
        });

        return;
      }

      this.setState({
        request,
        clear,
        loading: false,
        error: "",
      });
    } catch (error) {
      console.error(
        "GET REQUEST DETAIL ERROR:",
        error
      );

      this.setState({
        request: null,
        clear: null,
        loading: false,
        error:
          "خطا در دریافت اطلاعات درخواست.",
      });
    }
  };

  handleBack() {
    this.props.navigate(-1);
  }

  handleChat() {
    console.log(
      "رفتن به گفتگو"
    );
  }

  handleAddRelated() {
    console.log(
      "افزودن درخواست مرتبط"
    );
  }

  render() {
    const {
      authenticated,
      request,
      clear,
      loading,
      error,
    } = this.state;

    if (!authenticated) {
      return null;
    }

    if (loading) {
      return <Loader />;
    }

    if (error) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-danger">
            {error}
          </div>
        </div>
      );
    }

    if (!request) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            درخواست پیدا نشد.
          </div>
        </div>
      );
    }

    const technician =
      request.repairman_model;

    const technicianName =
      technician
        ? `${technician.name || ""} ${
            technician.family || ""
          }`.trim()
        : "—";

    const requestStatus =
      getRequestStatus(
        request,
        clear
      );

    const totalReceived =
      Number(request.sum || 0);

    const suppliesCost =
      Number(request.abzar || 0);

    const totalFee =
      totalReceived -
      suppliesCost;

    const commissionPercent =
      Number(
        request.porsant || 0
      );

    const commissionAmount =
      totalFee > 0 &&
      commissionPercent > 0
        ? (totalFee *
            commissionPercent) /
          100
        : 0;

    const receiptImage =
      request.file1 &&
      request.file1 !== ""
        ? `${CLEAR_IMAGE_URL}/${request.file1}`
        : null;

    const relatedRequests =
      Array.isArray(
        request.siblings
      )
        ? request.siblings
        : [];

    return (
      <div dir="rtl">

      </div>
    );
  }
}

export default withRouter(RequestDetailPage);
